settings.custom_css:
#single-course-post-content .ld-tabs-navigation {
    display: none;
}

#single-course-post-content h1, #single-course-post-content h2 {
    color: #F2F2F2;
    font-family: "Libre Franklin", Sans-serif;
    font-size: 2rem;
    font-weight: 600;
    line-height: 100%;
    margin-bottom:24px;

}

.elementor-851 .elementor-element.elementor-element-c2645ac {
    font-size: 18px !important;
}

#single-course-post-content p {
  margin-bottom:56px;   
}

#single-course-post-content ul {
  list-style: none; /* quitamos los marcadores por defecto */
  padding-left: 0;
}

#single-course-post-content li {
  margin-top: 0;
  margin-bottom: 24px;
}

#single-course-post-content ul li {
  position: relative;
  padding-left: 32px; /* espacio para el cuadrado */
}
#single-course-post-content .learndash-wrapper .ld-tabs .ld-tabs-content .ld-tab-content {
    padding: 0;
}

#single-course-post-content ul li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.42em;
  width: 10px;
  height: 10px;
  background-color: #FD6A44;
  display: inline-block;
}

#single-course-content .ld-item-title {
line-height: 28px;
}

.elementor-851 .elementor-element.elementor-element-055ec04 
.learndash-wrapper .ld-item-list .ld-item-list-item:nth-child(even) {
    background-color: #116d660D;
}



#single-course-content .learndash-wrapper .ld-item-list .ld-item-list-item {
     border: none;
     border-radius: 0px;
     border-top:1px solid #11544F;
}

#single-course-content .learndash-wrapper .ld-item-list .ld-item-list-item:last-child {
    border-bottom: 1px solid #11544F;
}


#single-course-content .learndash-wrapper .ld-status-complete {
    
    background-color: var(--edublink-color-primary) !important;
}
#single-course-content .ld-item-list-actions { 
    display: none; 
    
}
#single-course-content .learndash-wrapper .ld-expand-button.ld-button-alternate .ld-icon {
    background-color: #bfbfbf00 !important;
}

#single-course-content .learndash-wrapper .ld-item-list .ld-item-list-item {
    margin: 0;
}

#single-course-content .learndash-wrapper .ld-status.ld-status-unlocked {
    color: #ffffff !important;
    background-color: #F7A1614D !important;
}

.ld-table-list-header {
    display:none !important;
    
}

.learndash-wrapper .ld-item-list .ld-item-list-item .ld-item-list-item-expanded:before {
display:none !important;
}

.learndash-wrapper .ld-table-list a.ld-table-list-item-preview:hover {
    color: #FC5C3A !important;
}

   #preview-course-elemt .edublink-course-details-card-preview {
     background-position: center center;
    background-repeat: no-repeat;
    background-size: cover;
    background-color: #ccc;
    border-radius: 5px;
    height: 235px;
    position: relative;  
   } 
      #preview-course-elemt .edublink-course-details-card-preview:after {
       content: "";
    height: 100%;
    width: 100%;
    background-color: var(--edublink-color-black);
    border-radius: 5px;
    opacity: .3;
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    right: 0;
   } 
   
  #preview-course-elemt .edublink-course-video-preview-area {
      display: flex
;
    align-items: center;
    justify-content: center;
    height: 100%;
  }
  
   #preview-course-elemt .edublink-course-video-popup {
    height: 70px;
    width: 70px;
    line-height: 70px;
    font-size: 20px;
    background: var(--edublink-color-white);
    color: var(--edublink-color-primary);
    border-radius: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2;
   }

#single-course-resume-boton a.ld-course-resume, #single-course-resume-boton a.custom-course-button {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    background-color: #FD6A44 !important;
    font-family: "Libre Franklin", Sans-serif;
    font-size: 20px;
    font-weight: 600;
    line-height: 100%;
    fill: #FFFFFF;
    color: #FFFFFF;
    border-style: solid;
    border-width: 1px 1px 1px 1px;
    border-color: #FD6A44;
    border-radius: 0px 0px 0px 0px;
    padding: 17px 0px 17px 0px;
}

#single-course-resume-boton .learndash-wrapper a.ld-course-resume:hover, #single-course-resume-boton a.custom-course-button:hover {
    background-color: #61CE7000 !important;
    color: #FD6A44;
    border-width: 1px 1px 1px 1px;
    border-color: #FD6A44;
    border-bottom: 1px solid !important;

}

@media (max-width: 640px) {
 #single-course-resume-boton .learndash-wrapper a.ld-course-resume {
        margin-left: 0px;
    }
}

#single-course-resume-boton .learndash-wrapper .ld-button:focus:not(.ld-button-transparent):not(.ld--ignore-inline-css) {
        outline-color: #FD6A44 ;
}

#single-course-action-btn .elementor-button,#single-course-action-btn input{
    width: 100%;
    background-color: #61CE7000;
    font-family: "Libre Franklin", Sans-serif;
    font-size: 20px;
    font-weight: 600;
    line-height: 100%;
    fill: #FD6A44;
    color: #FD6A44;
    border-style: solid;
    border-width: 1px 1px 1px 1px;
    border-color: #FD6A44;
    border-radius: 0px 0px 0px 0px;
    padding: 17px 0px 17px 0px; 
    
}

#single-course-action-btn .elementor-button:hover {
background-color: #FD6A44;
    color: #FFFFFF;
    
}

#more-courses-section b {
    font-family: "Libre Franklin", Sans-serif;
    font-size: 48px;
    font-weight: 700;
    line-height: 100%;
    color: #F2F2F2;
}

@media (max-width: 767px) {
#more-courses-section b {

    font-size: 30px;

}

}
